diff --git a/src/domain/sites.js b/src/domain/sites.js
new file mode 100644
index 0000000..330760e
--- /dev/null
+++ b/src/domain/sites.js
@@ -0,0 +1,23 @@
+// Kitchen sites: every location belongs to one site; the default site is `main`.
+import { AppError } from "../errors.js";
+
+export const DEFAULT_SITE = "main";
+
+/** Resolves an optional site argument (string or `{ site }`) to a site id. */
+export function resolveSite(opt) {
+  if (typeof opt === "string") return opt;
+  return opt?.site ?? DEFAULT_SITE;
+}
+
+/** One site, or AppError unknown_site. */
+export function getSite(store, id) {
+  const site = (store.data.sites ?? []).find((s) => s.id === id);
+  if (!site) throw new AppError("unknown_site", { id });
+  return site;
+}
+
+/** Set of location ids belonging to a site (throws unknown_site if unknown). */
+export function siteLocations(store, opt) {
+  const site = getSite(store, resolveSite(opt)).id;
+  return new Set(store.data.locations.filter((l) => l.site === site).map((l) => l.id));
+}
